def simplify_path(path):
    stack = []
    if not path:
        return "/"
    if path[-1] == "/":
        path = path[:-1]
    if path[0] == "/":
        path = path[1:]
    for dir in path.split("/"):
        if dir == "..":
            if len(stack) > 0:
                stack.pop()
        elif dir != "." and dir != "":
            stack.append(dir)
    result = ""
    for dir in stack:
        result += "/" + dir
    return result if len(result) > 1 else "/"
